/* Global styles: base typography, visible focus and no horizontal scroll from 320 px (REQ-01.33). */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-family:
    system-ui,
    -apple-system,
    'Segoe UI',
    Roboto,
    sans-serif;
  line-height: 1.5;
  color: #1a1a1a;
  background: #ffffff;
}

body {
  margin: 0;
  overflow-wrap: anywhere;
}

img,
svg {
  max-width: 100%;
}

:focus-visible {
  outline: 3px solid #0b57d0;
  outline-offset: 2px;
}

h1:focus {
  outline: none;
}

h1:focus-visible {
  outline: 3px solid #0b57d0;
}

button {
  font: inherit;
  min-height: 44px;
  min-width: 44px;
  padding: 0.5rem 1rem;
  cursor: pointer;
}

a {
  color: #0b57d0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
