/*
 * Global styles (D12: visual style inspired by the SURA site, without its logo, images or font).
 * Palette and shapes live in custom properties; components reuse them.
 * Contrast (WCAG AA) of each text/background pair is noted next to the token.
 * No horizontal scroll from 320 px (REQ-01.33, REQ-02.29, REQ-03.36).
 */

:root {
  /* Brand */
  --color-primary: #2d6df6; /* 4.54:1 on white; 3.75:1 on surface (large text / UI only) */
  --color-primary-dark: #0033a0; /* 10.6:1 on white; 8.76:1 on surface */
  --color-accent: #e3e829; /* CTA background */
  --color-accent-hover: #d2d714;
  --color-on-accent: #26328c; /* 8.26:1 on accent; 10.95:1 on white */
  --color-surface: #dfeaff; /* hero, selected plan, highlighted blocks */
  --color-surface-soft: #f5f8ff;

  /* Text and lines */
  --color-text: #1c1c24; /* 16.9:1 on white; 13.98:1 on surface */
  --color-text-muted: #3f3f41; /* 10.5:1 on white; 8.68:1 on surface */
  --color-link: #0b5fff; /* 5.13:1 on white */
  --color-border: #e7e7e7; /* decorative card borders */
  --color-border-strong: #6b6b70; /* inputs and UI boundaries: 5.3:1 on white, 4.38:1 on surface */
  --color-focus: #0033a0; /* focus ring: 10.6:1 on white, 8.76:1 on surface, 8:1 on accent */

  /* States */
  --color-error: #b3261e; /* 6.54:1 on white; 5.92:1 on error surface */
  --color-error-surface: #fdf1f0;
  --color-disabled-bg: #f2f2f2;
  --color-disabled-text: #5c5c61; /* 5.94:1 on disabled background */

  /* Shapes and layout */
  --radius-md: 0.5rem;
  --radius-pill: 1.75rem;
  --container-max: 72rem;
  --gutter: 1rem;
  --card-padding: 1rem;
  --font-family:
    system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

@media (min-width: 48rem) {
  :root {
    --gutter: 1.5rem;
    --card-padding: 1.5rem;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-family: var(--font-family);
  line-height: 1.5;
  color: var(--color-text);
  background: #ffffff;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  overflow-wrap: anywhere;
}

img,
svg {
  max-width: 100%;
}

/* Headings: primary blue, bold (SURA reference). */
h1,
h2 {
  color: var(--color-primary);
  font-weight: 700;
  line-height: 1.2;
}

/*
 * Every screen heading sits on a full-width light-blue hero band. The band is painted with
 * border-image outset, which is ink overflow: it never adds horizontal scroll.
 * h1 is at least 28 px bold, so #2D6DF6 on the hero (3.75:1) is large text (>= 3:1).
 */
h1,
.hero-bleed {
  border-image: linear-gradient(var(--color-surface), var(--color-surface)) fill 0 / 0 / 0 100vmax;
}

h1 {
  margin: 0 0 1.5rem;
  padding: 1.5rem 0;
  font-size: clamp(1.75rem, 1.25rem + 2.2vw, 2.75rem);
  letter-spacing: -0.01em;
}

h2 {
  font-size: 1.25rem;
}

/* Visible focus everywhere, dark blue so it keeps >= 3:1 on white, hero and yellow. */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

h1:focus {
  outline: none;
}

h1:focus-visible {
  outline: 3px solid var(--color-focus);
}

/* Buttons: secondary pill by default; `.btn-primary` is the yellow call to action. */
button {
  font: inherit;
  font-weight: 600;
