input.content:
/* One column at every width; no horizontal scroll from 320 px (REQ-01.33). */
.step1-form {
  display: grid;
  gap: 1.5rem;
  max-width: 40rem;
}

/* Each section is a card; the legend floats so it sits inside the card like a heading. */
fieldset {
  display: grid;
  gap: 1.25rem;
  margin: 0;
  padding: var(--card-padding);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: #ffffff;
  min-width: 0;
}

legend {
  float: left;
  width: 100%;
  margin: 0;
  padding: 0;
  color: var(--color-primary);
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.2;
}

.field {
  display: grid;
  gap: 0.375rem;
}

.field > label {
  font-weight: 600;
}

.field--checkbox {
  grid-template-columns: auto 1fr;
  align-items: start;
  column-gap: 0.75rem;
}

.field--checkbox > label {
  font-weight: 400;
}

.field--checkbox .help,
.field--checkbox .error {
  grid-column: 1 / -1;
}

input:not([type='checkbox']),
select {
  width: 100%;
  min-height: 48px;
  padding: 0.625rem 0.875rem;
  font: inherit;
  color: var(--color-text);
  background: #ffffff;
  border: 1px solid var(--color-border-strong);
  border-radius: var(--radius-md);
}

input:not([type='checkbox']):hover,
select:hover {
  border-color: var(--color-text-muted);
}

input:not([type='checkbox']):focus-visible,
select:focus-visible {
  border-color: var(--color-primary);
  outline-offset: 1px;
}

input[type='checkbox'] {
  /* Never shrink (D-E2E-1, F-03.3). */
  flex: none;
  width: 24px;
  height: 24px;
  margin: 0;
  accent-color: var(--color-primary);
}

input[aria-invalid='true'],
select[aria-invalid='true'] {
  border: 2px solid var(--color-error);
}

.required-mark {
  color: var(--color-error);
}

.help {
  margin: 0;
  color: var(--color-text-muted);
  font-size: 0.9375rem;
}

.error {
  margin: 0;
  padding-left: 0.625rem;
  border-left: 3px solid var(--color-error);
  color: var(--color-error);
  font-weight: 600;
}

.continue {
  justify-self: start;
}

@media (max-width: 30rem) {
  .continue {
    justify-self: stretch;
  }
}

